export const advMaterials: AuthoredMaterial[] = [
  { id: "jee-adv-phy-electromagnetic-induction-m01", topicId: "jee-adv-phy-electromagnetic-induction", title: "Electromagnetic Induction & AC", content: `**Faraday's law**: induced EMF = −dΦ/dt; **Lenz's law** fixes the sign (opposing the flux change), reflecting energy conservation. A rod of length L moving at v across a field B has motional EMF = BLv. **Self-inductance** stores energy ½LI²; **mutual inductance** couples two coils. In AC circuits, **reactances** are X_L = ωL and X_C = 1/ωC; impedance Z = √(R² + (X_L − X_C)²). **Series LCR resonance** occurs at ω = 1/√(LC), giving maximum current; the **quality factor** Q measures sharpness. Average power = V_rms I_rms cosφ. **LC oscillations** exchange energy between capacitor and inductor at ω = 1/√(LC).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-fluid-mechanics-m01", topicId: "jee-adv-phy-fluid-mechanics", title: "Fluid Mechanics", content: `**Pressure** at depth h: P = P₀ + ρgh. **Pascal's law** underlies hydraulic systems. **Archimedes' principle**: buoyant force = weight of displaced fluid. For ideal flow, the **continuity equation** A₁v₁ = A₂v₂ (mass conservation) and **Bernoulli's theorem** P + ½ρv² + ρgh = constant (energy conservation) apply — faster flow means lower pressure (lift, venturi, atomiser). Real fluids have **viscosity**; laminar flow is described by **Poiseuille's law** and a sphere's terminal velocity by **Stokes' law** F = 6πηrv. **Surface tension** minimises area, giving excess pressure 2T/r (drop), 4T/r (bubble), and capillary rise h = 2T cosθ/(ρgr).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-gravitation-m01", topicId: "jee-adv-phy-gravitation", title: "Gravitation", content: `**Newton's law**: F = Gm₁m₂/r². Gravitational field g = GM/r² and potential V = −GM/r (potential energy U = −GMm/r). **Kepler's laws**: (1) elliptical orbits with the Sun at a focus, (2) equal areas in equal times (angular-momentum conservation), (3) T² ∝ a³. For a satellite, **orbital velocity** v₀ = √(GM/r) and **escape velocity** v_e = √(2GM/R) = √2·v₀ (about 11.2 km/s for Earth). A **geostationary** satellite has a 24-hour period. Inside a uniform shell, g = 0; below the Earth's surface, g decreases linearly with depth.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-magnetostatics-m01", topicId: "jee-adv-phy-magnetostatics", title: "Moving Charges & Magnetostatics", content: `A charge experiences the **Lorentz force** F = q(E + v × B); a moving charge in a uniform B travels in a circle of radius r = mv/qB with period independent of speed. **Biot–Savart law** gives dB = (μ₀/4π)(I dl × r̂)/r²; the field at the centre of a loop is μ₀I/2R and along a long wire is μ₀I/2πd. **Ampère's law** ∮B·dl = μ₀I_enclosed gives B = μ₀nI inside a long solenoid and μ₀I/2πr for a wire. Two parallel currents attract (opposite currents repel), defining the ampere. A current loop of moment m = NIA feels torque τ = m × B.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-solid-state-m01", topicId: "jee-adv-chem-solid-state", title: "Solid State", content: `Crystalline solids have long-range order; **unit cells** (primitive, BCC, FCC) repeat in the lattice. **Coordination number and packing**: simple cubic (Z = 1, 52%), BCC (Z = 2, 68%, atoms touch along the body diagonal so a√3 = 4r), FCC/CCP (Z = 4, 74%, a√2 = 4r). **Density** ρ = ZM/(a³Nₐ). **Voids**: tetrahedral (2 per atom) and octahedral (1 per atom). **Defects**: Schottky (missing ion pairs, lowers density), Frenkel (ion displaced to interstitial). Doping and non-stoichiometry give **F-centres** (colour), and semiconductors (n-type/p-type). Magnetic solids: ferro-, ferri-, and antiferromagnetic.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-solutions-m01", topicId: "jee-adv-chem-solutions", title: "Solutions & Colligative Properties", content: `Concentration: molarity, molality, mole fraction, ppm. **Henry's law**: gas solubility ∝ partial pressure. **Raoult's law**: partial vapour pressure ∝ mole fraction; ideal solutions obey it (ΔH_mix = ΔV_mix = 0). Positive/negative deviations give minimum/maximum-boiling **azeotropes**. **Colligative properties** depend only on particle number: relative lowering of vapour pressure, **ΔTb = i·Kb·m**, **ΔTf = i·Kf·m**, and **osmotic pressure π = i·CRT**. The **van 't Hoff factor i** accounts for dissociation (>1) or association (<1) and lets you find abnormal molar masses. Osmosis and reverse osmosis have wide applications.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-p-block-m01", topicId: "jee-adv-chem-p-block", title: "p-Block Elements", content: `The p-block spans metals, metalloids, and non-metals with the widest property range. The **inert pair effect** stabilises lower oxidation states down a group. **Group 15**: N₂ inert; NH₃ (Haber), HNO₃ (Ostwald); allotropes of P. **Group 16**: O₂, O₃ (ozone); **H₂SO₄** (Contact process), the 'king of chemicals'. **Group 17 halogens**: strongest oxidisers (F₂ > Cl₂ > Br₂ > I₂), form HX acids (HF weakest but etches glass) and interhalogens. **Group 18 noble gases**: inert; **Xe** forms XeF₂/XeF₄/XeF₆. First-member anomalies arise from small size and absence of d-orbitals; drying/oxidising agents and oxoacids are common exam themes.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-carbonyl-m01", topicId: "jee-adv-chem-carbonyl", title: "Carbonyl Compounds & Named Reactions", content: `The polar **C=O** group undergoes **nucleophilic addition** (with HCN → cyanohydrin, with NaHSO₃, with alcohols → acetals, with Grignard reagents → alcohols). **α-Hydrogen** compounds undergo the **aldol condensation** (self) and **Cross-aldol**; without α-H, aldehydes give the **Cannizzaro reaction** (disproportionation). Oxidation distinguishes aldehydes (positive **Tollens'** silver mirror and **Fehling's**) from ketones. Named reactions: **Clemmensen** (Zn-Hg/HCl) and **Wolff–Kishner** (NH₂NH₂/KOH) reduce C=O to CH₂; **haloform** reaction tests methyl ketones; **Rosenmund** reduction makes aldehydes from acyl chlorides. Carboxylic acids are strongly acidic (resonance-stabilised carboxylate).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-matrices-determinants-m01", topicId: "jee-adv-math-matrices-determinants", title: "Matrices & Determinants", content: `A **matrix** is a rectangular array; multiplication is associative but **not commutative** (AB ≠ BA generally). The **determinant** is defined for square matrices; det(AB) = det(A)det(B) and det(Aᵀ) = det(A). A matrix is **invertible iff det ≠ 0** (non-singular); A⁻¹ = adj(A)/det(A). Elementary row operations, rank, and the properties of determinants (row/column swaps change sign; a repeated row gives 0) solve systems. **Cramer's rule** and the matrix method solve linear systems: unique solution when det ≠ 0; **consistent/inconsistent** cases arise when det = 0. Symmetric (Aᵀ = A) and skew-symmetric (Aᵀ = −A) matrices are key special types.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-permutations-combinations-m01", topicId: "jee-adv-math-permutations-combinations", title: "Permutations & Combinations", content: `The **fundamental principle of counting**: if one event occurs in m ways and another in n ways, together they occur in m×n ways. **Permutations** (order matters): nPr = n!/(n−r)!; arrangements of n distinct objects = n!, with repetition handled by dividing by factorials of identical items. **Combinations** (order irrelevant): nCr = n!/(r!(n−r)!), with nCr = nC(n−r) and Pascal's rule nCr + nC(r−1) = (n+1)Cr. Circular permutations of n objects = (n−1)!. Techniques: **gap method** (no two together), **grouping** (always together), **distribution** (identical/distinct into boxes), and the inclusion–exclusion principle.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-application-derivatives-m01", topicId: "jee-adv-math-application-derivatives", title: "Application of Derivatives", content: `The derivative dy/dx is the **slope of the tangent**; the normal's slope is its negative reciprocal. A function is **increasing** where f'(x) > 0 and **decreasing** where f'(x) < 0. **Critical points** occur where f'(x) = 0 or is undefined; the **first-derivative test** or **second-derivative test** (f'' > 0 → minimum, f'' < 0 → maximum) classifies extrema. **Points of inflection** are where concavity changes (f'' = 0 with sign change). **Rolle's** and the **Mean Value Theorem** guarantee special points. **Related rates** and **maxima–minima word problems** (optimisation) and small-change/approximation using differentials are core applications.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-sequences-series-m01", topicId: "jee-adv-math-sequences-series", title: "Sequences & Series", content: `An **AP** has common difference d: nth term a + (n−1)d, sum Sₙ = n/2[2a + (n−1)d]; the **arithmetic mean** of a and b is (a+b)/2. A **GP** has ratio r: nth term ar^(n−1), sum a(rⁿ−1)/(r−1), and infinite sum a/(1−r) for |r| < 1; the **geometric mean** is √(ab). The **AM ≥ GM ≥ HM** inequality is a powerful tool. **AGP** and special sums Σn = n(n+1)/2, Σn² = n(n+1)(2n+1)/6, Σn³ = [n(n+1)/2]² recur in problems. Telescoping and method-of-differences handle harder series.`, estimatedReadTime: 2, orderIndex: 0 }
];

